#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>
using namespace std;

int N;
vector<string> grid1, grid2;
vector<vector<int>> dists;

struct Edge {
    int src, dst, cap, cost;
    Edge(int s, int d, int c, int co) : src(s), dst(d), cap(c), cost(co) {}
};

struct MinCostFlow {
    int nodeCount;
    vector<int> dist, flow, parent;
    vector<Edge> edges;
    int totalFlow, totalCost;

    void init(int n) {
        nodeCount = n;
        dist.assign(n, INT_MAX);
        flow.assign(n, 0);
        parent.assign(n, -1);
    }

    void addEdge(int u, int v, int c, int co) {
        edges.push_back(Edge(u, v, c, co));
        edges.push_back(Edge(v, u, 0, -co));
    }

    void shortestPath(int source, int sink) {
        init(nodeCount);
        flow[source] = INT_MAX;
        dist[source] = 0;
        queue<int> q;
        vector<bool> inq(nodeCount, false);
        q.push(source);
        inq[source] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;
            for (size_t i = 0; i < edges.size(); ++i) {
                Edge& e = edges[i];
                if (e.cap > 0 && dist[e.dst] > dist[e.src] + e.cost) {
                    dist[e.dst] = dist[e.src] + e.cost;
                    flow[e.dst] = min(flow[e.src], e.cap);
                    parent[e.dst] = i;
                    if (!inq[e.dst]) {
                        q.push(e.dst);
                        inq[e.dst] = true;
                    }
                }
            }
        }
    }

    void compute(int source, int sink) {
        if (source == sink) {
            totalFlow = INT_MAX;
            totalCost = 0;
            return;
        }
        totalFlow = 0;
        totalCost = 0;
        while (true) {
            shortestPath(source, sink);
            if (flow[sink] == 0) break;
            for (int cur = sink; cur != source; cur = edges[parent[cur]].src) {
                int rev = parent[cur] ^ 1;
                edges[parent[cur]].cap -= flow[sink];
                edges[rev].cap += flow[sink];
                totalCost += edges[parent[cur]].cost * flow[sink];
            }
            totalFlow += flow[sink];
        }
    }
};

#define IN_NODE(x) (2 * (x))
#define OUT_NODE(x) (2 * (x) + 1)

MinCostFlow mcf;
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};

void bfs(int sx, int sy, vector<vector<int>>& dist) {
    dist.assign(N, vector<int>(N, -1));
    dist[sx][sy] = 0;
    queue<int> q;
    q.push(sx * N + sy);
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        int x = cur / N, y = cur % N;
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N || dist[nx][ny] != -1 || grid1[nx][ny] == 'Y') continue;
            if (isdigit(grid2[nx][ny]) && grid2[nx][ny] != '0' && (dist[x][y] + 1 <= dists[nx][ny] || dists[nx][ny] == -1)) {
                dist[nx][ny] = dist[x][y] + 1;
                if (dist[nx][ny] != dists[nx][ny]) q.push(nx * N + ny);
            } else if (dists[nx][ny] == -1 || dists[nx][ny] > dist[x][y] + 1) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push(nx * N + ny);
            }
        }
    }
}

void buildAll(vector<string>& m, vector<vector<vector<int>>>& all) {
    all.resize(N * N);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(m[i][j]) && m[i][j] != '0')
                bfs(i, j, all[i * N + j]);
}

void connect(int i1, int j1, int i2, int j2) {
    int u = i1 * N + j1;
    int v = i2 * N + j2 + N * N;
    mcf.addEdge(OUT_NODE(u), IN_NODE(v), 1000000, 0);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.txt", "rt", stdin);
#endif
    int n, t;
    cin >> n >> t;
    N = n;
    vector<string> a(n), b(n);
    int si = -1, sj = -1;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        for (int j = 0; j < n; ++j)
            if (a[i][j] == 'Z') {
                si = i;
                sj = j;
            }
    }
    grid1 = a;
    for (int i = 0; i < n; ++i) cin >> b[i];
    grid2 = b;
    vector<vector<int>> temp;
    vector<vector<vector<int>>> allDists;
    dists.assign(N, vector<int>(N, 1000000000));
    bfs(si, sj, temp);
    dists = temp;
    buildAll(a, allDists);
    mcf.init(4 * N * N + 2);
    int src = 4 * N * N, dst = src + 1;
    for (int i = 0; i < N * N; ++i) {
        mcf.addEdge(src, IN_NODE(i), 1000000, 0);
        mcf.addEdge(OUT_NODE(N * N + i), dst, 1000000, 0);
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (isdigit(a[i][j])) {
                int idx = i * N + j;
                mcf.addEdge(IN_NODE(idx), OUT_NODE(idx), 0, a[i][j] - '0');
            }
            if (isdigit(b[i][j])) {
                int idx = i * N + j + N * N;
                mcf.addEdge(IN_NODE(idx), OUT_NODE(idx), 0, b[i][j] - '0');
            }
        }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(b[i][j]) && b[i][j] != '0')
                for (int k = 0; k < (int)allDists.size(); ++k)
                    if (!allDists[k].empty()) {
                        int x = k / N, y = k % N;
                        if (allDists[k][i][j] == -1 || allDists[k][i][j] > t) continue;
                        connect(x, y, i, j);
                    }
    mcf.compute(src, dst);
    cout << mcf.totalFlow << endl;
    return 0;
}
